/*!
 * cytoscape-cola - browser UMD wrapper
 * Uses global `cola` variable from cola.min.js
 */
(function(){ 'use strict';
  var cola_layout = function(cytoscape, cola) {
    if(!cytoscape || !cola) return;
    var defaults = {
      animate: true, refresh: 1, maxSimulationTime: 4000, ungrabifyWhileSimulating: false,
      fit: true, padding: 30, boundingBox: undefined, nodeDimensionsIncludeLabels: false,
      ready: function(){}, stop: function(){},
      randomize: false, avoidOverlap: true, handleDisconnected: true,
      convergenceThreshold: 0.01, nodeSpacing: function(node){ return 10; },
      flow: undefined, alignment: undefined, gapInequalities: undefined,
      centerGraph: true,
      edgeLength: undefined, edgeSymDiffLength: undefined, edgeJaccardLength: undefined,
      unconstrIter: undefined, userConstIter: undefined, allConstIter: undefined
    };
    var getInfo = function(ele){ return ele.scratch('cola'); };
    var setInfo = function(ele, obj){ return ele.scratch('cola', obj); };
    function ColaLayout(options) {
      this.options = Object.assign({}, defaults, options);
    }
    ColaLayout.prototype.run = function() {
      var layout = this, options = this.options, cy = options.cy;
      var nodes = cy.nodes().not(':parent');
      var edges = cy.edges().not(':meta');
      var bb = options.boundingBox || cy.extent();
      if(options.ready){ options.ready(); }
      var colaNodes = nodes.map(function(node, i){
        var nbb = node.layoutDimensions(options);
        var pos = node.position();
        setInfo(node, {index: i});
        return { x: pos.x, y: pos.y, width: nbb.w, height: nbb.h, index: i };
      });
      var colaEdges = edges.map(function(edge){
        var src = getInfo(edge.source()), tgt = getInfo(edge.target());
        return { source: src ? src.index : 0, target: tgt ? tgt.index : 0 };
      });
      var d = cola.adaptor({
        trigger: function(e){
          if(e.type === 'tick' || e.type === 'end'){
            nodes.forEach(function(node, i){
              var cn = colaNodes[i];
              node.position({ x: cn.x, y: cn.y });
            });
            if(options.animate && e.type === 'tick'){ cy.fit(options.padding); }
          }
          if(e.type === 'end'){
            if(options.fit){ cy.fit(options.padding); }
            layout.emit('layoutstop');
            if(options.stop){ options.stop(); }
          }
        },
        kick: function(){ d.start(options.unconstrIter || 10, options.userConstIter || 10, options.allConstIter || 10, 0, true, true); }
      });
      d.nodes(colaNodes).links(colaEdges)
       .size([bb.w || cy.width(), bb.h || cy.height()])
       .linkDistance(options.edgeLength || 100)
       .avoidOverlaps(options.avoidOverlap !== false)
       .handleDisconnected(options.handleDisconnected !== false)
       .convergenceThreshold(options.convergenceThreshold || 0.01)
       .alpha(1).start(0,0,0,0,true,false);
      layout.emit('layoutstart');
      d.kick();
      return this;
    };
    ColaLayout.prototype.stop = function(){ return this; };
    cytoscape('layout', 'cola', ColaLayout);
  };
  if(typeof module !== 'undefined' && module.exports){ module.exports = cola_layout; }
  else if(typeof cytoscape !== 'undefined' && typeof cola !== 'undefined'){ cola_layout(cytoscape, cola); }
  else if(typeof window !== 'undefined'){
    window.cytoscapeCola = function(){ cola_layout(window.cytoscape, window.cola); };
    if(window.cytoscape && window.cola){ cola_layout(window.cytoscape, window.cola); }
  }
})();

if (typeof window !== "undefined") { window.cytoscapeCola = true; }

if (typeof window !== "undefined") { window.cytoscapeCola = true; }
